message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure, error, or missing prerequisite identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure, error message, or detected missing prerequisite.",
      "target_description": "A subsequent agent action intended to resolve that failure or satisfy the missing prerequisite."
    },
    {
      "name": "VERIFIES_PRIOR_ACTION_OUTCOME",
      "definition": "A subsequent action inspects or checks the state, output, or artifact produced by an earlier action in order to confirm that the earlier action had its intended effect.",
      "source_description": "An earlier action that produced or modified some state, file, or artifact.",
      "target_description": "A subsequent inspection or check action that confirms whether the expected state or result was achieved."
    },
    {
      "name": "WAITS_FOR_OPERATION_COMPLETION",
      "definition": "A subsequent agent action waits or polls for the completion of a previously initiated long-running operation before proceeding.",
      "source_description": "An earlier initiated long-running operation whose completion is still pending.",
      "target_description": "A subsequent wait or poll action that checks whether that operation has finished."
    },
    {
      "name": "ADAPTS_IMPLEMENTATION_TO_OBSERVED_ENVIRONMENT",
      "definition": "A subsequent action modifies configuration or source code to accommodate a characteristic of the execution environment (such as a dependency version, OS release, or available tooling) that was observed or inferred earlier.",
      "source_description": "An earlier observation or inference about an environment characteristic, capability, or dependency version.",
      "target_description": "A subsequent modification of configuration or source code intended to accommodate that observed characteristic."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent action consumes an artifact, output, or result produced by an earlier action as an input to its own execution.",
      "source_description": "An earlier action that produced an artifact, output, or usable result.",
      "target_description": "A subsequent action that consumes that artifact, output, or result as an input."
    }
  ]
}

